def raw(c,p): return subprocess.check_output(["git","show",c+":"+p])
def load(c,p): return json.loads(raw(c,p))
def flat(v,p=""):
    if isinstance(v,dict) and v:
        return {q:y for k,z in v.items() for q,y in flat(z,p+"/"+k.replace("~","~0").replace("/","~1")).items()}
