    return {p:v}
def strict(a,b): return type(a)==type(b) and a==b
def parsed_log(name):
    t=(M20/"logs"/(name+".stdout")).read_text()
    if t.lstrip().startswith("{"): return json.loads(t)
    raise ValueError(name)
def factored_log(name):
    t=(M20/"logs"/(name+".stdout")).read_text().splitlines()
    common=json.loads(next(s.split(" ",1)[1] for s in t if s.startswith("COMMON_TO_ALL56 ")))
    residual={int(s.split(" ",1)[0].split("/")[-1]):json.loads(s.split(" ",1)[1]) for s in t if s.startswith("/per56/")}
    return common,residual
